/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.3 Sales order shipments
/// controller class when generating shipments from the workbench form
/// </summary>
class METSalesOrderShipmentCreationControllerWorkbench extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
    /// <summary>Constuct new object</summary>
    /// <param name = "_args">Arguments</param>
    /// <param name = "_executionMode">Execution mode</param>
    /// <returns>New Controller Object</returns>
    public static METSalesOrderShipmentCreationControllerWorkbench construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
    {
        METSalesOrderShipmentCreationControllerWorkbench controller = new METSalesOrderShipmentCreationControllerWorkbench();
        controller.parmExecutionMode(_executionMode);
        controller.parmArgs(_args);
        controller.parmLoadFromSysLastValue(false);

        return controller;
    }

/// <summary>
/// New method specifying the service class method to call
/// </summary>
protected void new()
{
    super(classstr(METSalesOrderShipmentCreationService), methodstr(METSalesOrderShipmentCreationService, run), SysOperationExecutionMode::Synchronous);
}

    /// <summary>
    /// Create the RecordSortedList from selected records in workbench form
    /// This is to avoid reselecting the records from database
    /// </summary>
    /// <param name = "_formDataSource">Form <c>METSalesOrderShipmentWorkbench</c> SalesTable datasource</param>
    /// <returns>RecordSortedList of <c>SalesTable</c> records selected in the form</returns>
    RecordSortedList createRecordSortedList(FormDataSource _formDataSource)
    {
        RecordSortedList        soListShipmentId;
        SalesTable              salesTable;
        MultiSelectionHelper    selection;

        soListShipmentId = new RecordSortedList(tableNum(SalesTable));
        selection = MultiSelectionHelper::construct();
        selection.parmDatasource(_formDataSource);
        salesTable = selection.getFirst();

        // shipment id needs to be allocated in the ascending order of route stops per route
        soListShipmentId.sortOrder(fieldnum(SalesTable, METRoute),
                                   fieldnum(SalesTable, METRouteStopNum),
                                   fieldnum(SalesTable, RecId));

        // insert selected records in a recordSortedList sorted by route and route stops ascending
        while (salesTable)
        {
            if (!SalesTable::METSalesOrderNotPicked(salesTable.SalesId, salesTable.CustAccount, salesTable.METRoute))
            {
                soListShipmentId.ins(salesTable);
            }
            else
            {
                throw error(strFmt("@MET:SONotPicked",salesTable.SalesId));
            }

            salesTable = selection.getNext();
        }

        return soListShipmentId;
    }

    /// <summary>
    /// Main method
    /// </summary>
    /// <param name = "_args">Arguments</param>
    public static void main(Args _args)
    {
        METSalesOrderShipmentCreationContract               contract;
        METSalesOrderShipmentCreationControllerWorkbench    controller;
        const str emptyString = '';
        FormDataSource      formDS;
        TableId             callerTableId;
        FormRun             callingFormRun;
        METIFormRefresh     callingForm;

        if (!_args.caller())
        {
            throw error("@SYS22539");
        }

        callingFormRun = _args.caller() as FormRun;

        if (_args && callingFormRun)
        {
            callerTableId = _args.dataset();
            switch (callerTableId)
            {
                case tableNum(SalesTable):
                    // get the caller datasource
                    formDS = FormDataUtil::getFormDataSource(_args.record());
                    break;
            }

            // create controller
            controller = METSalesOrderShipmentCreationControllerWorkbench::construct(_args);
            
            // get contract object
            contract = controller.getDataContractObject();

            // make sure no packedQuery in this scenario for workbench, only for batch
            contract.parmPackedQuery(emptyString);

            // set created RecordSortedList in the contract
            contract.parmSalesOrderRecordSortedList(controller.createRecordSortedList(formDS));
            
            // don't show any dialog from workbench screen
            controller.parmShowDialog(false);

            // execute the service class
            controller.startOperation();

            // Refresh the workbench form to remove records created in the shipments
            if (callingFormRun != null && formHasMethod(callingFormRun, identifierStr(refresh)))
            {
                callingForm = callingFormRun as METIFormRefresh;
                callingForm.refresh();
            }
        }        
    }

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}
